use verus::prelude::*;
use verus::pervasive::seq::Seq;

verus! {

    /// Given a non‐empty vector of lowercase English letters `s`, returns
    /// its plural form:
    /// if `s` ends with `'s'`, appends `"es"`, otherwise appends `"s"`.
    pub fn solve(s: &Vec<char>) -> (result: Vec<char>)
        requires
            // non‐empty word
            s.len() > 0,
            // all chars are between 'a' and 'z'
            forall(|i: usize| i < s.len() ==> 'a' <= s[i] && s[i] <= 'z'),
        ensures
            // the result sequence is exactly s.to_seq() plus the right suffix
            let sseq = s.to_seq();
            if sseq.index(sseq.len() - 1) == 's' {
                result.to_seq() == sseq + Seq::from_slice(&['e','s'])
            } else {
                result.to_seq() == sseq + Seq::singleton('s')
            }
    {
        // We'll build `result` by first copying all of `s`,
        // then appending the appropriate suffix.
        let mut result: Vec<char> = Vec::new();

        // Copy loop
        let mut i: usize = 0;
        while i < s.len() {
            invariant(i <= s.len());
            invariant(result.len() == i);
            // Ghost‐level: the first i entries of result match the first i of s
            invariant(result.to_seq() == s.to_seq().prefix(i));
            result.push(s[i]);
            i += 1;
        }

        // Append suffix
        if s[s.len() - 1] == 's' {
            result.push('e');
            result.push('s');
        } else {
            result.push('s');
        }

        result
    }

}